// ==========================================
// 1. 核心通用配置與函式
// ==========================================
const pageSize = 4; // 每頁最多顯示的公司數量
const TIME_TOLERANCE_MS = 120000; // 容許時間差：2 分鐘 (120,000 毫秒)

// 千分位格式化函式
const formatPrice = (val) => {
  if (val === undefined || val === null || val === "" || isNaN(parseFloat(val))) return "--";
  return parseFloat(val).toLocaleString('en-US');
};

// 解析修改狀態時間點
function parseModifyStatusToMs(statusStr) {
  const str = String(statusStr || "").trim();
  let match = str.match(/(\d{1,2})\/(\d{1,2})\s+(\d{1,2}):(\d{1,2})修改/);
  if (match) {
    const month = parseInt(match[1], 10) - 1;
    const day = parseInt(match[2], 10);
    const hour = parseInt(match[3], 10);
    const minute = parseInt(match[4], 10);
    const currentYear = new Date().getFullYear();
    return new Date(currentYear, month, day, hour, minute, 0, 0).getTime();
  }
  match = str.match(/修改(?:\d+_)?(\d{2})(\d{2})-(\d{2})(\d{2})/);
  if (!match) return 0;
  const month = parseInt(match[1], 10) - 1;
  const day = parseInt(match[2], 10);
  const hour = parseInt(match[3], 10);
  const minute = parseInt(match[4], 10);
  const currentYear = new Date().getFullYear();
  return new Date(currentYear, month, day, hour, minute, 0, 0).getTime();
}

// 生成單一用戶的 Flex Carousel
function generateFlexCarousel(clients, amounts, statuses, links, changeTimes, bankAccountRaw, displayName = "") {
  let bankAccount = bankAccountRaw || "暫無帳號資訊";
  bankAccount = bankAccount.replace(/(北中壢分行)[\s\u3000]*/g, "$1\n");

  let anyNotIssued = false;
  let anyModifying = false; // 紀錄是否有任何帳單修改中
  let calculatedTotalAmount = 0;
  let latestTimeMs = 0;
  const clientTimesMs = [];
  const downloadableClients = [];

  for (let j = 0; j < clients.length; j++) {
    const checkAmt = amounts[j];
    const checkLink = String(links[j] || "").trim();
    const rawStatus = String(statuses[j] || "").trim();
    const ct = String(changeTimes[j] ?? "0").trim();
    const isModifying = ct !== "0" && ct !== "";
    const isNotIssued = checkLink === "尚未出帳" || String(checkAmt).includes("#N/A");

    if (isNotIssued) anyNotIssued = true;
    if (isModifying) anyModifying = true;

    if (!isNotIssued && !isModifying) {
      downloadableClients.push(clients[j]);
      if (!isNaN(parseFloat(checkAmt))) {
        calculatedTotalAmount += parseFloat(checkAmt);
      }
    }

    const timeMs = parseModifyStatusToMs(rawStatus);
    clientTimesMs.push(timeMs);
    if (timeMs > latestTimeMs) latestTimeMs = timeMs;
  }

  const isLatestModified = [];
  for (let j = 0; j < clients.length; j++) {
    const rawStatus = String(statuses[j] || "").trim();
    const hasModifyMark = rawStatus.includes("修改");
    isLatestModified.push(clients.length > 1 && hasModifyMark);
  }

  const bubbles = [];

  let downloadButton = null;

  if (anyNotIssued) {
    downloadButton = {
      "type": "button",
      "action": {
        "type": "postback",
        "label": "尚未出帳，無法下載",
        "data": "action=bill_not_ready"
      },
      "style": "primary",
      "color": "#888888"
    };
  } else if (anyModifying) {
    downloadButton = {
      "type": "button",
      "action": {
        "type": "postback",
        "label": "⚠️ 帳單修改中 (暫不可下載)",
        "data": "action=bill_not_ready"
      },
      "style": "primary",
      "color": "#888888"
    };
  } else {
    const downloadClientNames = downloadableClients.join(',');
    const allPostbackData = `action=download_bill&clients=${downloadClientNames}`;
    downloadButton = {
      "type": "button",
      "action": {
        "type": "postback",
        "label": "下載全部帳單",
        "data": allPostbackData,
        "displayText": "正在下載帳單，請稍候..."
      },
      "style": "primary",
      "color": "#1DB446"
    };
  }

  const coverBubble = {
    "type": "bubble",
    "size": "mega",
    "header": {
      "type": "box",
      "layout": "vertical",
      "contents": [
        { "type": "text", "text": "🔔 帳單通知", "weight": "bold", "size": "xl", "color": "#111111" }
      ]
    },
    "body": {
      "type": "box",
      "layout": "vertical",
      "spacing": "md",
      "contents": [
        { 
          "type": "text", 
          "text": "請協助核對帳單，如有錯誤請儘速告知修正：", 
          "wrap": true, 
          "size": "md", 
          "color": "#111111" 
        },
        { "type": "separator", "margin": "md" },

        // ❶ 下載帳單
        {
          "type": "box",
          "layout": "horizontal",
          "spacing": "md",
          "margin": "md",
          "contents": [
            {
              "type": "text",
              "text": "❶",
              "size": "xl",
              "color": "#1DB446",
              "weight": "bold",
              "flex": 0,
              "gravity": "center"
            },
            {
              "type": "box",
              "layout": "vertical",
              "flex": 1,
              "contents": [
                { "type": "text", "text": "下載帳單", "weight": "bold", "size": "lg", "color": "#111111" },
                { "type": "text", "text": "點下方按鈕下載帳單明細", "size": "sm", "color": "#666666", "margin": "xs" }
              ]
            }
          ]
        },

        // ❷ 費用總覽
        {
          "type": "box",
          "layout": "horizontal",
          "spacing": "md",
          "margin": "md",
          "contents": [
            {
              "type": "text",
              "text": "❷",
              "size": "xl",
              "color": "#1DB446",
              "weight": "bold",
              "flex": 0,
              "gravity": "center"
            },
            {
              "type": "box",
              "layout": "vertical",
              "flex": 1,
              "contents": [
                { "type": "text", "text": "費用總覽", "weight": "bold", "size": "lg", "color": "#111111" },
                { "type": "text", "text": "右滑查看各公司應繳金額", "size": "sm", "color": "#666666", "margin": "xs" }
              ]
            }
          ]
        },

        // ❸ 匯款對帳
        {
          "type": "box",
          "layout": "horizontal",
          "spacing": "md",
          "margin": "md",
          "contents": [
            {
              "type": "text",
              "text": "❸",
              "size": "xl",
              "color": "#1DB446",
              "weight": "bold",
              "flex": 0,
              "gravity": "center"
            },
            {
              "type": "box",
              "layout": "vertical",
              "flex": 1,
              "contents": [
                { "type": "text", "text": "匯款對帳", "weight": "bold", "size": "lg", "color": "#111111" },
                { "type": "text", "text": "完成後請提供資訊對帳", "size": "sm", "color": "#666666", "margin": "xs" }
              ]
            }
          ]
        }
      ]
    }
  };

  if (downloadButton) {
    coverBubble.footer = {
      "type": "box",
      "layout": "vertical",
      "contents": [downloadButton]
    };
  }

  bubbles.push(coverBubble);

  const isMultiPage = clients.length > pageSize;
  for (let i = 0; i < clients.length; i += pageSize) {
    const currentBatch = clients.slice(i, i + pageSize);
    const isLastBubble = (i + pageSize) >= clients.length;
    const rows = [];
    let pageSubtotal = 0;

    currentBatch.forEach((name, index) => {
      const realIndex = i + index;
      const isLastItemInBatch = index === currentBatch.length - 1;
      let valAmount = amounts[realIndex];
      let displayAmount = formatPrice(valAmount);
      const rawStatus = String(statuses[realIndex] || "").trim();
      const rawLink = String(links[realIndex] || "").trim();
      const ct = String(changeTimes[realIndex] ?? "0").trim();

      const isNotIssued = rawLink === "尚未出帳" || String(valAmount).includes("#N/A");
      const isModifying = ct !== "0" && ct !== "";

      if (!isNotIssued && !isModifying && !isNaN(parseFloat(valAmount))) {
        pageSubtotal += parseFloat(valAmount);
      }

      const timeMs = clientTimesMs[realIndex];
      const isTheNewestOne = latestTimeMs > 0 && timeMs > 0 && (latestTimeMs - timeMs) <= TIME_TOLERANCE_MS;

      let displayNameWithMark = name || "未知公司";
      if (clients.length > 1 && isTheNewestOne) {
        displayNameWithMark = `✨ ${displayNameWithMark}`;
      }

      let contentBox = [];
      if (isNotIssued) {
        contentBox = [
          { "type": "text", "text": displayNameWithMark, "weight": "bold", "size": "lg", "color": "#111111", "wrap": true },
          { "type": "text", "text": "該用戶尚未出帳", "size": "sm", "color": "#999999", "margin": "xs", "style": "italic" }
        ];
      } else if (isModifying) {
        contentBox = [
          { "type": "text", "text": displayNameWithMark, "weight": "bold", "size": "lg", "color": "#E67E22", "wrap": true },
          {
            "type": "box",
            "layout": "horizontal",
            "margin": "xs",
            "contents": [
              {
                "type": "text",
                "text": "⏳ 帳單修改中，請稍候",
                "size": "sm",
                "color": "#E67E22",
                "weight": "bold",
                "style": "italic"
              }
            ]
          }
        ];
      } else {
        const targetColor = isTheNewestOne ? "#E67E22" : "#111111";
        const textInfoContents = [
          {
            "type": "text",
            "text": `金額：${displayAmount}`,
            "size": "sm",
            "color": targetColor,
            "weight": "bold"
          }
        ];

        if (rawStatus !== "") {
          textInfoContents.push({
            "type": "text",
            "text": rawStatus,
            "size": "sm",
            "color": targetColor,
            "weight": "bold",
            "margin": "xs"
          });
        }

        const detailsRowContents = [
          {
            "type": "box",
            "layout": "vertical",
            "flex": 1,
            "contents": textInfoContents
          }
        ];

        if (isLatestModified[realIndex]) {
          const displayStatus = rawStatus !== "" ? rawStatus : "修改";
          detailsRowContents.push({
            "type": "button",
            "action": {
              "type": "postback",
              "label": "下載",
              "data": `action=download_bill&clients=${name}`,
              "displayText": `正在下載 ${name} ${displayStatus} 的帳單`
            },
            "style": "primary",
            "color": "#E67E22",
            "height": "sm",
            "flex": 0,
            "gravity": "center"
          });
        }

        contentBox = [
          { "type": "text", "text": displayNameWithMark, "weight": "bold", "size": "lg", "color": isTheNewestOne ? "#E67E22" : "#111111", "wrap": true },
          { "type": "box", "layout": "horizontal", "margin": "xs", "contents": detailsRowContents }
        ];
      }

      if (!isLastItemInBatch) contentBox.push({ "type": "separator", "margin": "md" });
      rows.push({ "type": "box", "layout": "vertical", "margin": "lg", "spacing": "xs", "contents": contentBox });
    });

    if (isMultiPage) {
      rows.push({ "type": "separator", "margin": "xl", "color": "#eeeeee" });
      rows.push({ "type": "box", "layout": "horizontal", "margin": "md", "contents": [{ "type": "text", "text": "本頁小計", "size": "sm", "color": "#888888", "gravity": "center" }, { "type": "text", "text": `NT$ ${formatPrice(pageSubtotal)}`, "size": "md", "weight": "bold", "color": "#111111", "align": "end" }] });
    }

    if (isLastBubble) {
      rows.push({ "type": "separator", "margin": "xl", "color": "#eeeeee" });
      rows.push(
        { "type": "text", "text": "合計總金額", "size": "sm", "color": "#888888", "align": "end", "margin": "md" },
        { "type": "text", "text": `NT$ ${formatPrice(calculatedTotalAmount)}`, "size": "xxl", "weight": "bold", "color": "#E63946", "align": "end", "adjustMode": "shrink-to-fit" }
      );
    }

    const pageIndex = (i / pageSize) + 1;
    const headerTitle = isMultiPage ? `📋 帳單總覽 (${pageIndex})` : "📋 帳單總覽";

    const bubble = { 
      "type": "bubble", 
      "size": "mega", 
      "header": { 
        "type": "box", "layout": "vertical", "contents": [{ "type": "text", "text": headerTitle, "weight": "bold", "size": "xl", "color": "#111111" }] 
      }, 
      "body": { 
        "type": "box", "layout": "vertical", "contents": rows 
      } 
    };

    if (isLastBubble) {
      bubble.footer = {
        "type": "box",
        "layout": "vertical",
        "contents": [
          {
            "type": "box",
            "layout": "vertical",
            "backgroundColor": "#F7F7F7",
            "paddingAll": "md",
            "cornerRadius": "sm",
            "action": {
              "type": "clipboard",
              "clipboardText": bankAccountRaw || bankAccount
            },
            "contents": [
              {
                "type": "box",
                "layout": "horizontal",
                "contents": [
                  { "type": "text", "text": "🏦 匯款帳號", "size": "sm", "color": "#888888", "weight": "bold" },
                  { "type": "text", "text": "📋 點擊複製", "size": "xs", "color": "#1DB446", "align": "end", "weight": "bold" }
                ]
              },
              { "type": "text", "text": bankAccount, "size": "lg", "color": "#111111", "weight": "bold", "wrap": true, "margin": "xs" }
            ]
          }
        ]
      };
    }

    bubbles.push(bubble);
  }

  return {
    flexJsonString: JSON.stringify({ "type": "carousel", "contents": bubbles }),
    anyNotIssued: anyNotIssued
  };
}

// ==========================================
// 2. 模式自動偵測與資料解析
// ==========================================
const firstInput = $input.first()?.json || {};

if (Array.isArray(firstInput["客戶名稱"])) {
  const clients = firstInput["客戶名稱"] || [];
  const amounts = firstInput["帳單金額"] || [];
  const statuses = firstInput["狀態"] || [];
  const links = firstInput["JPG連結"] || [];
  const changeTimes = firstInput["變更時間"] || [];
  const bankAccountRaw = Array.isArray(firstInput["匯款帳號"]) ? firstInput["匯款帳號"][0] : firstInput["匯款帳號"];

  const result = generateFlexCarousel(clients, amounts, statuses, links, changeTimes, bankAccountRaw);

  return [{
    json: {
      flexJsonString: result.flexJsonString,
      clientNames: clients,
      anyNotIssued: result.anyNotIssued,
      mode: "A"
    }
  }];

} else {
  const paidContacts = $('取得可傳帳單名單').all()
    .map(item => item.json)
    .filter(contact => {
      const uId = contact["B:userId"] || contact["userId"];
      return uId && String(uId).trim() !== "";
    });

  const allBills = $('取得所有帳單明細').all()
    .map(item => item.json)
    .filter(b => {
      if (!b) return false;
      const hasCode = b["編號"] && String(b["編號"]).trim() !== "";
      const hasClientName = b["客戶名稱"] && String(b["客戶名稱"]).trim() !== "";
      return hasCode && hasClientName;
    });

  const billMap = {};
  allBills.forEach(b => {
    if (b["編號"]) billMap[String(b["編號"]).trim()] = b;
  });

  const lineTasks = [];
  const personToCompanies = {};
  const updateCodesSet = new Set();
  const groupedContacts = {};

  paidContacts.forEach(contact => {
    const userId = contact["B:userId"] || contact["userId"];
    if (!userId) return;

    if (!groupedContacts[userId]) {
      groupedContacts[userId] = {
        userId: userId,
        displayName: contact["C:displayName"] || contact["displayName"],
        allCodes: new Set()
      };
    }

    for (let i = 1; i <= 10; i++) {
      const codeVal = contact[`編號${i}`];
      if (codeVal && String(codeVal).trim() !== "") {
        groupedContacts[userId].allCodes.add(String(codeVal).trim());
      }
    }
  });

  Object.values(groupedContacts).forEach(userGroup => {
    const userId = userGroup.userId;
    const displayName = userGroup.displayName;
    const matchedBills = [];

    userGroup.allCodes.forEach(cleanCode => {
      const matchedBill = billMap[cleanCode];
      if (matchedBill) {
        matchedBills.push(matchedBill);
        updateCodesSet.add(cleanCode);
        if (displayName && matchedBill["客戶名稱"]) {
          if (!personToCompanies[displayName]) personToCompanies[displayName] = new Set();
          personToCompanies[displayName].add(matchedBill["客戶名稱"].trim());
        }
      }
    });

    if (matchedBills.length === 0) return;

    const clients = matchedBills.map(b => b["客戶名稱"]);
    const amounts = matchedBills.map(b => b["帳單金額"]);
    const statuses = matchedBills.map(b => b["狀態"]);
    const links = matchedBills.map(b => b["JPG連結"]);
    const changeTimes = matchedBills.map(b => b["變更時間"]);
    const bankAccountRaw = matchedBills[0]["匯款帳號"];

    const result = generateFlexCarousel(clients, amounts, statuses, links, changeTimes, bankAccountRaw, displayName);

    lineTasks.push({
      userId: userId,
      flexJsonString: result.flexJsonString
    });
  });

  const tgKeys = Object.keys(personToCompanies).filter(k => personToCompanies[k].size > 0);
  let tgText = "<b>📊 已發送帳單摘要</b>\n";
  let tgKeysCount = tgKeys.length;
  tgText += `<code>共計發送至 ${tgKeysCount} 個帳號</code>\n\n`;
  tgKeys.forEach(name => {
    tgText += `<b>🟢 ${name}</b>\n`;
    Array.from(personToCompanies[name]).forEach(company => {
      tgText += ` • ${company}\n`;
    });
    tgText += "\n";
  });

  const updateList = Array.from(updateCodesSet).map(code => ({ json: { "編號": code } }));

  return [{
    json: {
      lineTasks: lineTasks,
      tgText: tgText,
      updateList: updateList,
      mode: "B"
    }
  }];
}

