  if (downloadButton) {
    coverBubble.footer = {
      "type": "box",
      "layout": "vertical",
      "contents": [downloadButton]
    };
  }

  bubbles.push(coverBubble);

  const isMultiPage = clients.length > pageSize;
  for (let i = 0; i < clients.length; i += pageSize) {
    const currentBatch = clients.slice(i, i + pageSize);
    const isLastBubble = (i + pageSize) >= clients.length;
    const rows = [];
    let pageSubtotal = 0;

    currentBatch.forEach((name, index) => {
      const realIndex = i + index;
      const isLastItemInBatch = index === currentBatch.length - 1;
      let valAmount = amounts[realIndex];
      let displayAmount = formatPrice(valAmount);
      const rawStatus = String(statuses[realIndex] || "").trim();
      const rawLink = String(links[realIndex] || "").trim();
      const ct = String(changeTimes[realIndex] ?? "0").trim();

      const isNotIssued = rawLink === "尚未出帳" || String(valAmount).includes("#N/A");
      const isModifying = ct !== "0" && ct !== "";

      if (!isNotIssued && !isModifying && !isNaN(parseFloat(valAmount))) {
        pageSubtotal += parseFloat(valAmount);
      }

      const timeMs = clientTimesMs[realIndex];
      const isTheNewestOne = latestTimeMs > 0 && timeMs > 0 && (latestTimeMs - timeMs) <= TIME_TOLERANCE_MS;

      let displayNameWithMark = name || "未知公司";
      if (clients.length > 1 && isTheNewestOne) {
        displayNameWithMark = `✨ ${displayNameWithMark}`;
