        ];
      } else if (isModifying) {
        contentBox = [
          { "type": "text", "text": displayNameWithMark, "weight": "bold", "size": "lg", "color": "#E67E22", "wrap": true },
          {
            "type": "box",
            "layout": "horizontal",
            "margin": "xs",
            "contents": [
              {
                "type": "text",
                "text": "⏳ 帳單修改中，請稍候",
                "size": "sm",
                "color": "#E67E22",
                "weight": "bold",
                "style": "italic"
              }
            ]
          }
        ];
      } else {
        const targetColor = isTheNewestOne ? "#E67E22" : "#111111";
        const textInfoContents = [
          {
            "type": "text",
            "text": `金額：${displayAmount}`,
            "size": "sm",
            "color": targetColor,
            "weight": "bold"
          }
